-- Original: server/internal/quest/upstream/projecteq/kael/Svekk_Fangbinder.pl (sha256 dbc1dcd4a6bf412ab8a2b62f314359b3c6bf5c92365af128b9f8ffe477f82e88)
-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
-- P99 and source dialogue agree on 100 gold for the torque; correct the mismatching 15 platinum source reward.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("Greetings, " .. e.other:GetCleanName() .. ".  I am Svekk, a humble servant of Wenglawks.  It is my job to keep track of the supplies here.  I also sell mundane wares.")
  elseif e.message:findi("supplies") then
    e.self:Say("We have all kinds of supplies!  Normally we deliver them to the giants who live outside Kael.")
  elseif e.message:findi("giants") then
    e.self:Emote("There are several encampments in the eastern wastes that barter for supplies with us monthly.  The great divide also has a small outpost of Kromrif who strive to beat the Coldain back into their city of Thurgadin and of course the outposts in the wakening lands.  Our last batch of deliveries did not reach their intended targets.  The runners have not been heard from since they were dispatched either.")
  elseif e.message:findi("eastern wastes") then
    e.self:Say("The Kromrif of the Eastern wastes are more savage than those who dwell within Kael Drakkel.  Normally they can fend for themselves but recently Fjloaren of the Icebane clan has requested we help them with a shipment of supplies.  We have yet to receive payment for the supplies but you are more than welcome to purchase supplies for them and deliver them.  It has been a most unforgiving season upon the wastes I believe.")
  elseif e.message:findi("wakening land") then
    e.self:Emote("Korzak Stonehammer is the name of the man whom we usually deliver to in the Wakening Land.  His men are attempting to expand Kael further into that accursed forest.  If you buy a pack of supplies and deliver it to him I am sure he would repay you handsomely.  A single pack will only cost you a mere five hundred pieces of gold.")
  elseif e.message:findi("great divide") then
    e.self:Say("If you wish to deliver supplies to the warriors in the great divide that is wonderful. One small problem arises.   I do not know you, " .. e.other:GetRaceName() .. ".  I would not trust you as far as I could throw a dragon.  If you pay for the supplies and deliver them the men at the fortress will surely repay you.  A pack of basic supplies only costs a meager five hundred gold pieces.  If you choose to purchase the supplies and deliver them take them to a man named Bekerak Coldbones at the outpost.")
  elseif e.message:findi("klezendian") then
    e.self:Emote("Klezendian crystals can be found in the Crystal Caverns beneath the eastern wastes.  The Rygorr orcs mine Velium and various metals from its rich walls.  Be warned though, the crystal caverns are not a safe place, nameless beasts and even some Coldain call It their home.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { gold = 500 }) then
    e.self:Emote("heaves a large pack from a pile in the corner and sets it before you.")
    e.other:AddEXP(250)
    e.other:SummonItem(25266)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25278 }) then
    e.self:Say("Ahh, a Velium torque! Here, I will give you one hundred pieces of gold for that!")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(429, 10, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:AddMoneyToPP(0, 0, 100, 0, true)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25267 }) then
    e.self:Say("I can get most of these supplies ready, but I have no source for Klezendian Crystals. Return with a crystal and this voucher.")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(429, 10, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:SummonItem(25270)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25270, item2 = 25271 }) then
    e.self:Say("I have the other supplies ready for your trip.")
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(429, 10, 0)
    e.other:Faction(430, -30, 0)
    e.other:AddEXP(250)
    e.other:SummonItem(25269)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
